import{_ as l,r as t,o as i,c as u,e as p,a as n,s as e,d as a}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"事件 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"基本用法","slug":"基本用法","link":"#基本用法","children":[]},{"level":2,"title":"订阅事件","slug":"订阅事件","link":"#订阅事件","children":[{"level":3,"title":"注册监听器的位置","slug":"注册监听器的位置","link":"#注册监听器的位置","children":[]},{"level":3,"title":"使用优先级订阅","slug":"使用优先级订阅","link":"#使用优先级订阅","children":[]},{"level":3,"title":"停止事件传播","slug":"停止事件传播","link":"#停止事件传播","children":[]},{"level":3,"title":"通配符监听器","slug":"通配符监听器","link":"#通配符监听器","children":[]}]},{"level":2,"title":"触发事件","slug":"触发事件","link":"#触发事件","children":[]},{"level":2,"title":"按引用传递参数","slug":"按引用传递参数","link":"#按引用传递参数","children":[{"level":3,"title":"队列事件","slug":"队列事件","link":"#队列事件","children":[]}]},{"level":2,"title":"使用类作为监听器","slug":"使用类作为监听器","link":"#使用类作为监听器","children":[{"level":3,"title":"订阅单个方法","slug":"订阅单个方法","link":"#订阅单个方法","children":[]},{"level":3,"title":"订阅整个类","slug":"订阅整个类","link":"#订阅整个类","children":[]}]},{"level":2,"title":"事件发射器 Trait","slug":"事件发射器-trait","link":"#事件发射器-trait","children":[]}],"relativePath":"3.x/zh-cn/extend/services/event.md","filePath":"3.x/zh-cn/extend/services/event.md"}'),k={name:"3.x/zh-cn/extend/services/event.md"};function r(d,s,g,v,h,m){const o=t("pre-heading"),c=t("post-heading");return i(),u("div",null,[p(o),s[0]||(s[0]=n("h1",null,"事件",-1)),p(c),s[1]||(s[1]=e(`<h2 id="基本用法"><a href="#基本用法" class="header-anchor">#</a> 基本用法</h2><p><code>Event</code> 类提供了一个简单的观察者实现，允许你在应用程序中订阅和监听事件。例如，你可以监听用户登录的事件并更新其最后登录日期。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">last_login</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DateTime</span><span class="token punctuation">;</span>
    <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>此事件通过 <code>Event::fire</code> 方法触发，该方法作为用户登录逻辑的一部分被调用，从而使逻辑可扩展。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,5)),s[2]||(s[2]=n("div",{class:"custom-block tip"},[n("p",null,[a("有关 October CMS 本身提供的所有事件列表，请参阅 "),n("a",{href:"https://octobercms.com/docs/api",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("API 文档"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a("。")])],-1)),s[3]||(s[3]=e(`<h2 id="订阅事件"><a href="#订阅事件" class="header-anchor">#</a> 订阅事件</h2><p><code>Event::listen</code> 方法主要用于订阅事件，可以在应用程序代码的任何位置调用。第一个参数是事件名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第二个参数可以是一个闭包，指定在事件触发时应执行的操作。闭包可以接受一些可选参数，这些参数由触发的事件提供。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$arg1</span><span class="token punctuation">,</span> <span class="token variable">$arg2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 做一些事情</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你还可以传递对任何可调用对象的引用或专用事件类，它将被使用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;LoginHandler&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>可调用方法可以选择指定全部、部分或不指定参数。无论如何，除非指定了过多的参数，否则事件不会抛出任何错误。</p></div><h3 id="注册监听器的位置"><a href="#注册监听器的位置" class="header-anchor">#</a> 注册监听器的位置</h3><p>最常见的位置是<a href="./../extending.html">插件注册文件</a>的 <code>boot</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>另外，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，用于放置事件注册逻辑。例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>由于这些方法都没有本质上的&quot;正确&quot;与否，你可以根据应用程序的大小选择你觉得合适的方法。</p><h3 id="使用优先级订阅"><a href="#使用优先级订阅" class="header-anchor">#</a> 使用优先级订阅</h3><p>在订阅事件时，你还可以将优先级作为第三个参数指定。优先级较高的监听器将先运行，而具有相同优先级的监听器将按订阅顺序运行。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 先运行</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 后运行</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="停止事件传播"><a href="#停止事件传播" class="header-anchor">#</a> 停止事件传播</h3><p>有时你可能希望阻止事件传播到其他监听器。你可以通过从监听器返回 <code>false</code> 来实现：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 处理事件</span>

    <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="通配符监听器"><a href="#通配符监听器" class="header-anchor">#</a> 通配符监听器</h3><p>注册事件监听器时，你可以使用星号指定通配符监听器。通配符监听器首先接收被触发的事件名称，然后接收作为数组传递给事件的参数。</p><p>以下监听器处理所有以 <code>foo.</code> 开头的事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo.*&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 处理事件...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你可以使用 <code>Event::firing</code> 方法来确定触发了哪个事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo.*&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">firing</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;foo.bar&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="触发事件"><a href="#触发事件" class="header-anchor">#</a> 触发事件</h2><p>你可以在代码的任何位置使用 <code>Event::fire</code> 方法使逻辑可扩展。这意味着其他开发者，甚至你自己的内部代码，可以&quot;挂钩&quot;到代码的这个点并注入特定的逻辑。第一个参数应该是事件名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;myevent&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>始终建议使用你的插件命名空间代码作为事件名称的前缀，这将防止与其他插件冲突。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第二个参数是一个值数组，将作为参数传递给订阅该事件的事件监听器。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$arg1</span><span class="token punctuation">,</span> <span class="token variable">$arg2</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第三个参数指定事件是否应该是可停止事件，意味着如果返回了&quot;非 null&quot;值，它应该停止。此参数默认设置为 false。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果事件是可停止的，将捕获返回的第一个值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 单个结果，事件已停止</span>
<span class="token variable">$result</span> <span class="token operator">=</span> <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>否则，它以数组的形式返回所有事件的所有响应的集合。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 多个结果，所有事件都已触发</span>
<span class="token variable">$results</span> <span class="token operator">=</span> <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="按引用传递参数"><a href="#按引用传递参数" class="header-anchor">#</a> 按引用传递参数</h2><p>在处理或过滤传递给事件的值时，你可以在变量前加上 <code>&amp;</code> 以按引用传递。这允许多个监听器操作结果并将其传递给下一个。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在监听事件时，参数也需要在闭包定义中使用 <code>&amp;</code> 符号声明。在下面的例子中，<code>$content</code> 变量将在结果后附加 &quot;AB&quot;。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$content</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;A&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$content</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;B&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="队列事件"><a href="#队列事件" class="header-anchor">#</a> 队列事件</h3><p>触发事件可以与<a href="./queue.html">队列</a>配合延迟执行。使用 <code>Event::queue</code> 方法将事件&quot;排队&quot;以备触发，但不立即触发。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">queue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你可以使用 <code>Event::flush</code> 方法刷新所有排队的事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">flush</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="使用类作为监听器"><a href="#使用类作为监听器" class="header-anchor">#</a> 使用类作为监听器</h2><p>在某些情况下，你可能希望使用类而不是闭包来处理事件。类事件监听器将从<a href="./application.html">应用程序 IoC 容器</a>中解析，为你的监听器提供完整的依赖注入功能。</p><h3 id="订阅单个方法"><a href="#订阅单个方法" class="header-anchor">#</a> 订阅单个方法</h3><p>事件类可以像其他任何类一样使用 <code>Event::listen</code> 方法注册，将类名作为字符串传递。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token class-name static-context">LoginHandler</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>默认情况下，将调用 <code>LoginHandler</code> 类上的 <code>handle</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">LoginHandler</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">handle</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果你不想使用默认的 <code>handle</code> 方法，可以指定应该订阅的方法名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token class-name static-context">LoginHandler</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;onLogin&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="订阅整个类"><a href="#订阅整个类" class="header-anchor">#</a> 订阅整个类</h3><p>事件订阅者是可以在类内部订阅多个事件的类。订阅者应定义一个 <code>subscribe</code> 方法，该方法将接收一个事件调度器实例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UserEventHandler</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * subscribe 注册订阅者的监听器。
     * @param  Illuminate\\Events\\Dispatcher  $events
     * @return array
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">subscribe</span><span class="token punctuation">(</span><span class="token variable">$events</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$events</span><span class="token operator">-&gt;</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token keyword static-context">static</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;userLogin&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$events</span><span class="token operator">-&gt;</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.logout&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token keyword static-context">static</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;userLogout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * userLogin 处理用户登录事件。
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">userLogin</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * userLogout 处理用户登出事件。
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">userLogout</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>一旦定义了订阅者，就可以使用 <code>Event::subscribe</code> 方法注册它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">subscribe</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserEventHandler</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你也可以使用<a href="./application.html">应用程序 IoC 容器</a>来解析你的订阅者。为此，只需将订阅者的名称传递给 <code>subscribe</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">subscribe</span><span class="token punctuation">(</span><span class="token class-name static-context">UserEventHandler</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="事件发射器-trait"><a href="#事件发射器-trait" class="header-anchor">#</a> 事件发射器 Trait</h2><p>有时你希望将事件绑定到单个对象实例。你可以通过在类中实现 <code>October\\Rain\\Support\\Traits\\Emitter</code> trait 来使用替代事件系统。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UserManager</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Support<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Emitter</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>此 trait 提供了一个使用 <code>bindEvent</code> 监听事件的方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$manager</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">UserManager</span><span class="token punctuation">;</span>
<span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.beforeRegister&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 检查 $user 是否是垃圾邮件发送者</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>fireEvent</code> 方法用于触发事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$manager</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">UserManager</span><span class="token punctuation">;</span>
<span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.beforeRegister&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>这些事件仅发生在本地对象上，而不是全局的。</p>`,73))])}const x=l(k,[["render",r]]);export{b as __pageData,x as default};
